`bsearch` is a standard binary search that also counts how many elements it compares. What does this code print, and why are the two results different?

def bsearch(a, x):
    lo, hi, steps = 0, len(a) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        steps += 1
        if a[mid] == x:
            return mid, steps
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, steps

data = [7, 3, 9, 1, 5, 8, 2]
print(bsearch(data, 9), bsearch(sorted(data), 9))

This class simulates how a dynamic array such as a Python list grows: when it is full, it moves every item into a new block twice as large and counts the moved items. What does it print? What do the numbers tell you about the cost of a single append and of n appends?

class DynArray:
    def __init__(self):
        self.size, self.cap, self.copies = 0, 1, 0

    def append(self, x):
        if self.size == self.cap:
            self.copies += self.size  # move every item to a bigger block
            self.cap *= 2
        self.size += 1

for n in [16, 17, 1000]:
    arr = DynArray()
    for i in range(n):
        arr.append(i)
    print(n, arr.cap, arr.copies)
